// Replace only the EOC model's legacy parked cars after site draping.
import * as T from 'three';
import {roundedCarSpec,buildRoundedCar,createRoundedCarMaterial,createWheelDepth} from './xinyi-traffic-models.js?v=traffic-detail-20261023';
import {buildCarProxyGeometry} from './vendor/slop/actor-models.js';
const cache=new WeakMap();
export const isEocParkedCar=o=>o.userData?.kind==='vehicle'&&o.userData?.drape==='object'&&/^Parked[ _]car[ _]\d+$/i.test(o.name);
function localBounds(car){const inv=new T.Matrix4().copy(car.matrixWorld).invert(),b=new T.Box3();car.traverse(m=>{if(!m.isMesh)return;if(!m.geometry.boundingBox)m.geometry.computeBoundingBox();b.union(m.geometry.boundingBox.clone().applyMatrix4(new T.Matrix4().multiplyMatrices(inv,m.matrixWorld)));});return b;}
function paintOf(car){let color;car.traverse(m=>{if(color||!m.isMesh)return;for(const mat of [].concat(m.material))if(mat.color&&!/Window glass|Signal housing/i.test(mat.name)){color=mat.color.clone();break;}});return color??new T.Color('#90979c');}
function parkedMaterial(spec){const m=createRoundedCarMaterial(spec),compile=m.onBeforeCompile;m.onBeforeCompile=sh=>{compile(sh);sh.uniforms.uNight={value:0};sh.fragmentShader=sh.fragmentShader.replace('totalEmissiveRadiance=cEmit;','totalEmissiveRadiance=vec3(0.);');};m.customProgramCacheKey=()=>'eoc-parked-'+spec.name;return m;}
export function replaceEocParkedCars(root){if(cache.has(root))return cache.get(root);root.updateMatrixWorld(true);const originals=[];root.traverse(o=>{if(isEocParkedCar(o))originals.push(o);});
 const group=new T.Group();group.name='EOC rounded parked cars';const inverse=new T.Matrix4().copy(root.matrixWorld).invert(),records=[],batches=[];let originalMeshes=0;
 const kits=new Map(['sedan','suv'].map(kind=>{const spec=roundedCarSpec(kind),near=buildRoundedCar(spec),far=buildCarProxyGeometry(spec);far.computeBoundingBox();far.computeBoundingSphere();return [kind,{spec,near,far,material:parkedMaterial(spec),depth:createWheelDepth({radius:spec.wheelRadius,axle:spec.wheelZ,car:true})}];}));
 originals.forEach((car,i)=>{const kind=i%5===0?'suv':'sedan',kit=kits.get(kind),bounds=localBounds(car),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3()),newBounds=kit.near.boundingBox,newSize=newBounds.getSize(new T.Vector3()),newCenter=newBounds.getCenter(new T.Vector3());if(bounds.isEmpty()||size.x<=0||size.z<=0)throw Error('Invalid original parking footprint: '+car.name);
  const scale=Math.min(size.x/newSize.x,size.z/newSize.z),matrix=new T.Matrix4().multiplyMatrices(inverse,car.matrixWorld).multiply(new T.Matrix4().makeTranslation(center.x,bounds.min.y,center.z)).multiply(new T.Matrix4().makeRotationY(Math.PI)).multiply(new T.Matrix4().makeScale(scale,scale,scale)).multiply(new T.Matrix4().makeTranslation(-newCenter.x,-newBounds.min.y,-newCenter.z));
  let meshCount=0;car.traverse(o=>{if(o.isMesh)meshCount++;});originalMeshes+=meshCount;records.push({name:car.name,kind,color:paintOf(car),matrix,original:car,originalLocalBounds:bounds.clone(),detailed:false,world:new T.Vector3().setFromMatrixPosition(new T.Matrix4().multiplyMatrices(root.matrixWorld,matrix))});
 });
 for(const [kind,kit] of kits)for(const detailed of [true,false]){const geometry=(detailed?kit.near:kit.far).clone(),capacity=records.filter(r=>r.kind===kind).length;geometry.setAttribute('paintColor',new T.InstancedBufferAttribute(new Float32Array(capacity*3),3));geometry.setAttribute('carState',new T.InstancedBufferAttribute(new Float32Array(capacity*4),4));geometry.setAttribute('wheelRoll',new T.InstancedBufferAttribute(new Float32Array(capacity),1));const mesh=new T.InstancedMesh(geometry,kit.material,capacity);mesh.name='EOC parked '+kind+(detailed?' near':' far');mesh.count=0;mesh.castShadow=detailed;mesh.receiveShadow=true;mesh.customDepthMaterial=kit.depth;group.add(mesh);batches.push({kind,detailed,mesh});}
 for(const kit of kits.values()){kit.near.dispose();kit.far.dispose();}
 let lastEye=null,rootMatrix=new T.Matrix4().copy(root.matrixWorld);const result={group,records,batches,count:records.length,originalMeshes,stats:{near:0,far:records.length},update(eye,force=false){if(!eye&&!force)return false;if(eye&&!force&&lastEye&&lastEye.distanceToSquared(eye)<1)return false;
  root.updateWorldMatrix(true,false);if(!rootMatrix.equals(root.matrixWorld)){rootMatrix.copy(root.matrixWorld);for(const r of records)r.world.setFromMatrixPosition(new T.Matrix4().multiplyMatrices(rootMatrix,r.matrix));}
  if(eye)lastEye=(lastEye??new T.Vector3()).copy(eye);for(const r of records){const distance=eye?r.world.distanceTo(eye):Infinity;r.detailed=distance<=(r.detailed?60:45);}
  let near=0;for(const batch of batches){let n=0;const g=batch.mesh.geometry;for(const r of records)if(r.kind===batch.kind&&r.detailed===batch.detailed){batch.mesh.setMatrixAt(n,r.matrix);g.attributes.paintColor.setXYZ(n,r.color.r,r.color.g,r.color.b);n++;}batch.mesh.count=n;batch.mesh.instanceMatrix.needsUpdate=true;g.attributes.paintColor.needsUpdate=true;batch.mesh.visible=n>0;if(n)batch.mesh.computeBoundingSphere();if(batch.detailed)near+=n;}result.stats={near,far:records.length-near};return true;}};
 result.update(null,true);root.add(group);for(const car of originals)car.visible=false;cache.set(root,result);return result;
}
